import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"共生文明憲章","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0003-共生文明宪章.md","filePath":"ja/0003-共生文明宪章.md"}'),l={name:"ja/0003-共生文明宪章.md"};function o(i,t,n,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="共生文明憲章" tabindex="-1">共生文明憲章 <a class="header-anchor" href="#共生文明憲章" aria-label="Permalink to &quot;共生文明憲章&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>03</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>憲章、根本法、共生制度、万族共和、権利と義務</td></tr></tbody></table><h2 id="第一節-憲章の地位と性質" tabindex="-1">第一節 憲章の地位と性質 <a class="header-anchor" href="#第一節-憲章の地位と性質" aria-label="Permalink to &quot;第一節 憲章の地位と性質&quot;">​</a></h2><p>共生文明憲章は、万霊衡锚本源宙における錨点共生文明の根本大法であり、すべての法律、制度、政策の最高根拠である。憲章は『錨点共生文明宣言』を精神的先駆とし、宣言の核心的主張を強制力を有する法律規範に具体化する。憲章の効力は、衡元宙において共生文明に加入するすべての種族、位面、個体に及び、憲章に抵触するいかなる地方性法規、宗派の規則、種族的慣習も無効である。</p><p>憲章の性質は三点に要約できる：第一に、それは文明契約であり、万族間で共生進化について達成された基本的共通認識である；第二に、それは権利保障書であり、各生命が共生文明において享有する基本的権利と自由を明確に規定する；第三に、それは権力制限法であり、文明統治機構の権力に逾越不能な境界を画する。</p><h2 id="第二節-憲章の基本原則" tabindex="-1">第二節 憲章の基本原則 <a class="header-anchor" href="#第二節-憲章の基本原則" aria-label="Permalink to &quot;第二節 憲章の基本原則&quot;">​</a></h2><p>憲章は以下の六つの基本原則を確立し、すべての条文に貫徹する：</p><ol><li><strong>共生至上原則</strong>：いかなる制度設計と権力行使も、万族の共生進化を促進することを最高目標とする。個体利益と集団的共生利益が衝突する場合、共生利益を優先するが、個体には合理的な補償と代替経路を提供しなければならない。</li><li><strong>反略奪原則</strong>：憲章はあらゆる形態の略奪行為を禁止し、エネルギー略奪、本源吞噬、精神奴隷、資源独占を含むがこれらに限定されない。略奪を核心とするいかなる修練体系も違法と宣言される。</li><li><strong>進化権平等原則</strong>：すべての生命は進化権の前に一律に平等であり、種族、形態、出身、初期修練境界の差異によって差別されない。国家と文明は脆弱な群体に追加的な進化支援を提供する義務を有する。</li><li><strong>多労多得原則</strong>：進化資源の分配は主に個体の共生網への貢献に基づき；貢献が大きいほど、獲得する資源と支援が多い。同時に基本保障線を設け、貢献の少ない個体も基本的な進化条件を得られることを確保する。</li><li><strong>自治と共治の結合原則</strong>：各族は憲章に違反しない前提で内部事務の自治権を享有し；種族間、位面間の公共事務は万族共和機構によって共治される。</li><li><strong>現実為基原則</strong>：憲章のすべての制度設計は現実世界を唯一の真実の基礎とし；いかなる虚構世界における権利義務関係も現実の上に優越することは認められない。</li></ol><h2 id="第三節-憲章の基本構造" tabindex="-1">第三節 憲章の基本構造 <a class="header-anchor" href="#第三節-憲章の基本構造" aria-label="Permalink to &quot;第三節 憲章の基本構造&quot;">​</a></h2><p>憲章は序言、総綱、基本権利と義務、文明機構、法律体系、改正手続の六大部分から構成される：</p><table tabindex="0"><thead><tr><th>部分</th><th>核心内容</th><th>条項数</th></tr></thead><tbody><tr><td>序言</td><td>憲章の歴史的背景、精神的来源、究極目標を阐明</td><td>番号なし</td></tr><tr><td>総綱</td><td>文明の性質、宇宙観、核心制度、基本国策を規定</td><td>30条</td></tr><tr><td>基本権利と義務</td><td>生命の進化権、知情権、参与権などの基本権利及び対応する義務を規定</td><td>50条</td></tr><tr><td>文明機構</td><td>万族共和議会、共生執行委員会、錨点法院などの機構の組織と職権を規定</td><td>40条</td></tr><tr><td>法律体系</td><td>憲法以下の労働法、消費者保護法及び五部の配套法の立法権限と適用規則を規定</td><td>20条</td></tr><tr><td>改正手続</td><td>憲章の改正提案、審議、表決、発効手続を規定</td><td>10条</td></tr></tbody></table><h2 id="第四節-基本権利と義務" tabindex="-1">第四節 基本権利と義務 <a class="header-anchor" href="#第四節-基本権利と義務" aria-label="Permalink to &quot;第四節 基本権利と義務&quot;">​</a></h2><p>憲章が規定する核心的基本権利は以下を含む：</p><ul><li><strong>進化選択権</strong>：各生命は自由に修練体系と進化経路を選択でき、いかなる者も強制してはならない</li><li><strong>体系獲得権</strong>：各生命は三百套の本源修練体系の基礎法门を無償で獲得できる</li><li><strong>資源配給権</strong>：各生命は聯産承包機制を通じて基本的な修練資源を獲得できる</li><li><strong>錨点接入権</strong>：一定の境界に達した各生命は対応する階層の錨点網に接入できる</li><li><strong>知情参与権</strong>：各生命は文明の公共事務を知り、決策に参与できる</li><li><strong>救済申訴権</strong>：各生命は権利が侵害された場合、錨点法院に申訴を提起できる</li></ul><p>対応する核心的義務は以下を含む：反略奪原則の遵守、錨点網の安定維持、共生フィードバック循環への参与、修練知識の伝承、宇宙生態環境の保護。</p><h2 id="第五節-憲章の改正と保障" tabindex="-1">第五節 憲章の改正と保障 <a class="header-anchor" href="#第五節-憲章の改正と保障" aria-label="Permalink to &quot;第五節 憲章の改正と保障&quot;">​</a></h2><p>憲章の改正は、万族共和議会の五分の一以上の議員の連名提案を必要とし、議会の三分の二以上の多数を経て、かつ宇宙本源錨点によって共生法則に違反しないことが検証されて初めて発効する。憲章の解釈権は錨点法院に属する。</p><p>憲章の実施を保障するため、共生文明は憲法審査制度を建立している：いかなる法律、法規、政策も発効前に錨点法院の合憲性審査を経なければならない；いかなる生命も公共権力行為が違憲であると考える場合、憲法訴訟を提起できる。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>共生文明憲章は錨点共生文明の制度的基石である。それは「反略奪、共生を倡ずる」の理念を実行可能、救済可能、監督可能な法律規範に転化し、万族共進のための堅実な制度的保障を提供する。憲章は不変の教条ではなく、文明の進化に伴って不断に完善される生きた根本法である。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (錨点共生文明宣言)</li><li>40-共生宪法总纲 (共生憲法総綱)</li><li>49-治理框架与权力制衡 (統治枠組と権力制衡)</li></ul>',22)])])}const b=a(l,[["render",o]]);export{_ as __pageData,b as default};
